import{_ as e,o as a,c as s,a3 as r}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Mostrar nível de sigilo dos documentos","description":"","frontmatter":{"title":"Mostrar nível de sigilo dos documentos","id":"eproc-nivel-sigilo-documentos","plataforma":"eproc","grupo":"Eventos","plano":"free","desde":"1.10.0","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-nivel-sigilo-documentos"}]]},"headers":[],"relativePath":"funcionalidades/eproc-nivel-sigilo-documentos.md","filePath":"funcionalidades/eproc-nivel-sigilo-documentos.md"}'),n={name:"funcionalidades/eproc-nivel-sigilo-documentos.md"};function t(l,o,i,d,c,u){return a(),s("div",null,o[0]||(o[0]=[r('<h1 id="mostrar-nivel-de-sigilo-dos-documentos" tabindex="-1">Mostrar nível de sigilo dos documentos <a class="header-anchor" href="#mostrar-nivel-de-sigilo-dos-documentos" aria-label="Permalink to &quot;Mostrar nível de sigilo dos documentos&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>O eproc só informa o sigilo de um documento no balão que aparece ao passar o mouse sobre ele. Este recurso põe, ao lado de cada documento sigiloso da tabela de eventos, um pequeno selo com o nível de sigilo, para você identificar de relance os documentos que as partes não veem.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, página do processo, tabela de eventos.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><p>Abra um processo:</p><ol><li>Os documentos sigilosos ganham, logo depois do nome, um selo com o ícone de olho riscado e o número do nível (por exemplo, <strong>1</strong> para &quot;Segredo de Justiça&quot;).</li><li>Passe o mouse sobre o selo para ver o nome completo do nível.</li><li>Para trocar o nível, clique no selo e escolha <strong>Sem sigilo</strong>, <strong>Segredo de justiça</strong> ou <strong>Sigiloso interno</strong>. O eploc faz a alteração em segundo plano, confere o nível gravado, e o selo fica verde com o novo nível. Para os demais níveis, use <strong>Abrir a tela de sigilo deste documento</strong>, no mesmo menu.</li></ol><p>A cor do selo acompanha o nível: azul para o nível 1, laranja para os níveis 2 e 3 e vermelho para os níveis 4 e 5.</p><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Opção</th><th>Padrão</th><th>Efeito</th></tr></thead><tbody><tr><td>Mostrar o selo a partir do</td><td>Nível 1</td><td>Esconde os selos dos níveis mais baixos. Escolha &quot;Nível 2&quot;, por exemplo, para não marcar os documentos em segredo de justiça.</td></tr></tbody></table><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>Documentos sem sigilo (nível 0) não ganham selo.</li><li>O nível é lido do próprio balão do eproc, sem consultas extras ao sistema.</li><li>Se a troca em segundo plano não der certo, a tela de sigilo do eproc é aberta para você concluir.</li><li>A troca rápida só oferece os níveis 0 a 2, por segurança.</li><li>Com o recurso &quot;Apontar documentos com sigilo nível 3 em processos migrados (TJMG)&quot; ligado, os documentos que já têm a marca dele não recebem um segundo selo.</li></ul>',13)]))}const g=e(n,[["render",t]]);export{m as __pageData,g as default};
